const ALIASES = {
  meal: 'food',
  bowl: 'food',
  exercise: 'workout',
  dumbbell: 'workout',
  scale: 'body',
  weight: 'body',
  drink: 'water',
  fire: 'calorie',
  grain: 'carbs',
  avocado: 'fat',
  calendar: 'plan',
  target: 'mission',
  trophy: 'achievement',
  pencil: 'edit',
  arrow_right: 'chevron_right',
  add: 'plus',
  remove: 'minus'
};

function resize(svg, size) {
  const n = String(size).replace(/[^0-9.]/g, '') || '56';
  return svg.replace(/width="64"/, `width="${n}"`).replace(/height="64"/, `height="${n}"`);
}

function label(svg, text) {
  if (!text) return svg;
  return svg.replace(/aria-label="[^"]*"/, `aria-label="${String(text).replace(/"/g, '&quot;')}"`);
}

const LEGACY_SVG_MAP = {
  'i-bowl': 'today', 'i-apple': 'food', 'i-fit': 'workout', 'i-chart': 'chart',
  'i-gear': 'gear', 'i-users': 'users', 'i-run': 'run', 'i-clipcheck': 'clipboard',
  'i-target': 'target', 'i-chat': 'chat'
};

function getIcon(name, size, opt = '') {
  if (typeof opt === 'string') opt = opt ? { label: opt } : {};
  opt = opt || {};
  const key = LEGACY_SVG_MAP[name] || name;

  /* TILE tier — explicit {tile:true} (behavior v10.33 เดิม) */
  if (opt.tile === true) {
    if (window.IUMaster) {
      const m = window.IUMaster.getIcon(key, size || 56, { variant: opt.variant, label: opt.label });
      if (m) return m;
    }
    const lk = ALIASES[key] || key;
    if (ICONS[lk]) return label(resize(ICONS[lk], size || 56), opt.label || '');
  }

  /* LINE tier — ใช้ PHICONS เดิม (เส้น คม มืออาชีพ) ผ่าน phic() */
  var PHIC_ALIAS = { edit: 'pencil', book: 'books', compass: 'refresh', door: 'lock', close: 'x', add: 'plus' };
  if (typeof window.phic === 'function') {
    var pk = PHIC_ALIAS[key] || key;
    var po = window.phic(pk, size || 22);
    if (po) return po;
  }

  /* fallback 1: TILE clean ขนาดเล็ก (master) */
  if (window.IUMaster && window.IUMaster.hasIcon(key, 'clean')) {
    return window.IUMaster.getIcon(key, size || 24, { variant: 'clean', label: opt.label });
  }

  /* fallback 2: legacy tile ICONS */
  const lk2 = ALIASES[key] || key;
  if (ICONS[lk2]) return label(resize(ICONS[lk2], size || 24), opt.label || '');

  /* fallback 3: question + TODO warn */
  try { console.warn('TODO missing icon: ' + name); } catch (e) {}
  if (typeof window.phic === 'function') { var q = window.phic('question', size || 22); if (q) return q; }
  return label(resize(ICONS.food, size || 24), opt.label || '');
}

function renderIcon(target, name, size = 56, ariaLabel = '') {
  const el = typeof target === 'string' ? document.querySelector(target) : target;
  if (el) el.innerHTML = getIcon(name, size, ariaLabel);
}

